m html.parser import HTMLParser\nimport json\n\nclass TableParser(HTMLParser):\n    def __init__(self):\n        super().__init__()\n        self.rows = []\n        self.current_row = []\n        self.in_td = False\n        self.current_data = ''\n        \n    def handle_starttag(self, tag, attrs):\n        if tag == 'td':\n            self.in_td = True\n        elif tag == 'tr':\n            self.current_row = []\n            \n    def handle_endtag(self, tag):\n        if tag == 'td':\n            self.current_row.append(self.current_data.strip())\n            self.current_data = ''\n            self.in_td = False\n        elif tag == 'tr':\n            if self.current_row:\n                self.rows.append(self.current_row)\n                \n    def handle_data(self, data):\n        if self.in_td:\n            self.current_data += data\n\n# Parse August 1970 bulletin SB-2 table\nwith open('/app/resources/treasury_bulletin_1970_08.json', 'r') as f:\n    data08 = json.load(f)\n\nelements = data08['document']['elements']\ntable_content = elements[583]['content']\n\nparser = TableParser()\nparser.feed(table_content)\n\n# Find the months section and extract sales\n# Looking for: Period | Sales | ...\nmonths_started = False\nsales_data_08 = []\n\nfor row in parser.rows:\n    if row and row[0] == 'Months:':\n        months_started = True\n        continue\n    if months_started and row and '1969' in row[0] or (row and '1970' in row[0]):\n        # Period is in first column, Sales is in second column\n        period = row[0]\n        sales = row[1]\n        if sales:\n            sales_data_08.append((period, sales))\n            print(f'{period}: {sales}')\n\nprint()\nprint('Total months found in August bulletin:', len(sales_data_08))\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
